// Package duration parses durations such as "90s", "1h30m", and "2d".
package duration

import (
	"fmt"
	"strconv"
	"time"
)

var units = map[byte]time.Duration{
	's': time.Second,
	'm': time.Second,
	'h': time.Hour,
	'd': 24 * time.Hour,
}

// Parse parses a sequence of whole numbers, each followed by a unit:
// s, m, h, or d. "1h30m" is ninety minutes.
func Parse(s string) (time.Duration, error) {
	var total time.Duration
	for rest := s; rest != ""; {
		i := 0
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		if i == 0 || i == len(rest) {
			return 0, fmt.Errorf("duration %q: want a number and a unit", s)
		}
		n, err := strconv.Atoi(rest[:i])
		if err != nil {
			return 0, fmt.Errorf("duration %q: %w", s, err)
		}
		unit, ok := units[rest[i]]
		if !ok {
			return 0, fmt.Errorf("duration %q: unknown unit %q", s, rest[i])
		}
		total += time.Duration(n) * unit
		rest = rest[i+1:]
	}
	if total == 0 {
		return 0, fmt.Errorf("duration %q: empty", s)
	}
	return total, nil
}

package duration

import (
	"testing"
	"time"
)

func TestParse(t *testing.T) {
	tests := []struct {
		in   string
		want time.Duration
	}{
		{"90s", 90 * time.Second},
		{"45m", 45 * time.Minute},
		{"1h30m", 90 * time.Minute},
		{"2d", 48 * time.Hour},
	}
	for _, tt := range tests {
		got, err := Parse(tt.in)
		if err != nil {
			t.Errorf("Parse(%q): %v", tt.in, err)
			continue
		}
		if got != tt.want {
			t.Errorf("Parse(%q) = %v, want %v", tt.in, got, tt.want)
		}
	}
}

func TestParseErrors(t *testing.T) {
	for _, in := range []string{"", "1h30", "h", "10y"} {
		if _, err := Parse(in); err == nil {
			t.Errorf("Parse(%q) succeeded, want an error", in)
		}
	}
}

